package kotlinx.rpc.grpc.benchmarks.client

import io.grpc.testing.integration.SimpleRequest
import io.grpc.testing.integration.SimpleResponse
import kotlinx.coroutines.flow.Flow
import kotlinx.rpc.grpc.client.GrpcClient

/** Adapts benchmark calls to the service API generated by a specific kotlinx-rpc version. */
internal interface BenchmarkBackend {
    val implementationName: String

    fun prepareUnaryCall(client: GrpcClient): suspend (SimpleRequest) -> SimpleResponse

    fun preparePingPongCall(client: GrpcClient): (Flow<SimpleRequest>) -> Flow<SimpleResponse>

    fun prepareClientStreamingCall(client: GrpcClient): suspend (Flow<SimpleRequest>) -> SimpleResponse

    fun prepareServerStreamingCall(client: GrpcClient): (SimpleRequest) -> Flow<SimpleResponse>

    fun prepareFullDuplexCall(client: GrpcClient): (Flow<SimpleRequest>) -> Flow<SimpleResponse>
}
